    t = (a.text() or '').replace('&','')
    if 'warp' in t.lower() or '再投影' in t or 'ワープ' in t:
        menu = a.parent()
        path = []
        while isinstance(menu, QMenu):
            path.insert(0, menu.title())
            menu = menu.parent()
        hits.append({
            'text': t,
            'objectName': a.objectName(),
            'enabled': a.isEnabled(),
            'visible': a.isVisible(),
            'menu_path': ' > '.join(path),
        })
result = hits"}

